from pathlib import Path
import json, sys
root=Path('.')
move_map=json.loads(Path('assets/evidence/migrations/20260611-process-artifact-migration-map.json').read_text(encoding='utf-8'))
old_paths=[item['from'] for item in move_map['moves']]
skip_prefixes=('assets/evidence/host-hooks/','assets/evidence/check-receipts/','assets/evidence/prism/')
skip_exact={'assets/evidence/migrations/20260611-process-artifact-migration-map.json','runtime/core/process_artifact_placement.py'}
allowed_suffixes={'.json','.jsonl','.md','.txt','.py','.sh'}
hits=[]
for path in root.rglob('*'):
    if not path.is_file():
        continue
    rel=path.as_posix()
    if '.git/' in rel or '/__pycache__/' in rel:
        continue
    if rel in skip_exact or rel.startswith(skip_prefixes):
        continue
    if path.suffix not in allowed_suffixes:
        continue
    try:
        text=path.read_text(encoding='utf-8')
    except UnicodeDecodeError:
        continue
    for old in old_paths:
        if old in text:
            hits.append(f'{rel}: {old}')
if hits:
    print('\n'.join(hits))
    sys.exit(1)
print('REDCAP_PROCESS_ARTIFACT_EXACT_OLD_PATH_ACTIVE_SCAN_OK')
